const output = prettier.format(src, options);
const expected = "'`@observer
class Store {
  @observable value: number = 0;

  @foo
  @bar baz() {
  }

  @computed get total() {
    return this.value;
  }
}
`;
assert.strictEqual(output, expected, '"'formatted output mismatch');
assert.strictEqual(prettier.format(output, options), output, 'format should be idempotent');
console.log('decorator formatting assertion passed');
NODE"

